import numpy as np
T={'1':np.ones_like(t),'st':np.sqrt(t),'t':t,'lt':np.log(t)}
Aa={'1':np.ones_like(A),'A':A,'A2':A**2,'sA':np.sqrt(A),'AlA':A*np.log(A),'lA':np.log(A),'A3':A**3,'iA':1/A}
cols=[];names=[]
for a,tv in T.items():
    for b,av in Aa.items():
        cols.append(tv*av);names.append(a+'*'+b)
X=np.array(cols).T
c,*_=np.linalg.lstsq(X,dA_dt,rcond=None)
print('full NMSE',np.mean((X@c-dA_dt)**2)/np.var(dA_dt))
# greedy backward elimination keeping NMSE small
keep=list(range(X.shape[1]))
def nm(k):
    cc,*_=np.linalg.lstsq(X[:,k],dA_dt,rcond=None)
    return np.mean((X[:,k]@cc-dA_dt)**2)/np.var(dA_dt)
while len(keep)>3:
    best=None
    for j in keep:
        k2=[i for i in keep if i!=j]
        e=nm(k2)
        if best is None or e<best[0]: best=(e,j)
    if best[0]>1e-10: 
        print('stop at',len(keep),best[0]); break
    keep.remove(best[1])
print([names[i] for i in keep], nm(keep))
cc,*_=np.linalg.lstsq(X[:,keep],dA_dt,rcond=None)
